from lib import *
from collections import defaultdict, Counter
fp=tab('NRFPRC'); fx=tab('NRFXRT')
# prices: latest publication per fund/date
best={}
for r in fp:
    k=(r['FP_FNDID'],r['FP_PRCDT'])
    if k not in best or r['FP_CHGTS']>best[k]['FP_CHGTS']: best[k]=r
pdates=defaultdict(list)
for (f,d) in best: pdates[f].append(d)
for f in pdates: pdates[f].sort()
rates={}
for r in fx: rates[(r['FX_CCY'].upper(),r['FX_RATDT'])]=r['FX_RATE']
fdates=defaultdict(list)
for (c,d) in rates: fdates[c].append(d)
for c in fdates: fdates[c]=sorted(set(fdates[c]))
def last(lst,d):
    i=bisect.bisect_right(lst,d); return lst[i-1]
def price(f,d,col='FP_BIDPR'): return best[(f,last(pdates[f],d))][col]
def rate(c,d): return rates[(c,last(fdates[c],d))]
funds=keyed(tab('NRFUND'),'FD_FNDID')
pol=grouped(tab('NRPOLH'),'PH_POLNR')
hold=defaultdict(list)
for r in target('t3_holding'): hold[(r['policy_id'],r['valuation_date'])].append(r)
sv=target('t3_surrender_value')
res=Counter(); ex=defaultdict(list)
for r in sv:
    k=(r['policy_id'],r['valuation_date']); d=dt.date.fromisoformat(r['valuation_date'])
    ccy=latest(pol[r['policy_id']],'PH')['PH_CCY']
    tot={m:Decimal(0) for m in ['sum_round','round_each','bid_noFx']}
    for h in hold[k]:
        u=Decimal(h['units']); f=h['fund_id']; fc=funds[f]['FD_CCY']
        p=price(f,d); x=rate(fc,d)/rate(ccy,d)
        tot['sum_round']+=u*p*x
        tot['round_each']+=cents(u*p*x)
    pv=Decimal(r['policy_value'])
    for m,v in tot.items():
        ok = cents(v)==pv
        res[m,ok]+=1
        if not ok and len(ex[m])<5: ex[m].append((k,pv,cents(v)))
print(res); 
for m in ex: print(m, ex[m])
