from lib import *
from collections import Counter, defaultdict
samp,bk,tb=pickle.load(open('samp.pkl','rb')); ev=pickle.load(open('ev.pkl','rb'))
tbm={r['booking_id']:r for r in tb}
rev={(r['EV_POLNR'],r['EV_REVNR']) for r in ev.values() if r['EV_EVTTP']==900}
S=set(samp)
hold=defaultdict(Decimal)
for r in target('t3_holding'):
    if r['policy_id'] in S: hold[(r['policy_id'],r['fund_id'],int(r['pot']),r['valuation_date'])]=Decimal(r['units'])
vds=['2006-12-31','2020-04-30','2025-12-31']
def units(r):
    if r['BK_UNITS'] is not None: return r['BK_UNITS']
    t=tbm.get(r['BK_BOOKID']); return Decimal(t['units']) if t else None
for datecol in ['BK_TRDDT','BK_PRCDT']:
    calc=defaultdict(Decimal)
    for r in bk:
        if (r['BK_POLNR'],r['BK_EVTNR']) in rev or ev[(r['BK_POLNR'],r['BK_EVTNR'])]['EV_EVTTP']==990: continue
        u=units(r)
        for v in vds:
            if r[datecol]<=dt.date.fromisoformat(v): calc[(r['BK_POLNR'],r['BK_FNDID'],int(r['BK_POTCD']),v)]+=u
    keys=set(hold)|{k for k,v in calc.items() if v!=0}
    bad=[k for k in keys if hold[k]!=calc[k]]
    print(datecol,len(keys),len(bad)); print(sorted(bad)[:10]); print([(hold[k],calc[k]) for k in sorted(bad)[:10]])
EOF
