from mkt import *
from collections import Counter, defaultdict
from neuron import add_months, months_between
from decimal import ROUND_DOWN, ROUND_HALF_UP
samp,bk,tb=pickle.load(open('samp.pkl','rb')); ev=pickle.load(open('ev.pkl','rb'))
tbm={r['booking_id']:r for r in tb}
S=set(samp)
prem={(r['PR_POLNR'],r['PR_EVTNR']):r for r in tab('NRPREM') if r['PR_POLNR'] in S}
brok=keyed(tab('NRBROK'),'BR_BRKNR'); entc=grouped(tab('NRENTC'),'EC_TIER')
agre=grouped(tab('NRAGRE'),'AG_POLNR','AG_FEETP')
prod=keyed(tab('NRPROD'),'PD_PRDCD'); allo=grouped(tab('NRALLO'),'AL_POLNR')
byev=defaultdict(list)
for r in bk:
    if r['BK_BKTYP']=='PRM' and r['BK_BOOKID'] in tbm: byev[(r['BK_POLNR'],r['BK_EVTNR'])].append(r)
c=Counter(); ex=defaultdict(list)
def ent(p,d):
    ag=[a for a in agre.get((p,'ENT'),[]) if a['AG_VLDFR']<=d<=a['AG_VLDTO']]
    if ag: return ag[0]['AG_RATE']
    ph=valid(pol[p],'PH',d)
    return valid(entc[brok[ph['PH_BRKNR']]['BR_TIER']],'EC',d)['EC_RATE']
for k,rows in byev.items():
    p=k[0]; pr=prem[k]; amt=sum(Decimal(tbm[r['BK_BOOKID']]['amount_pc']) for r in rows)
    era=rows[0]['BK_TRDDT']<dt.date(2007,8,11)
    oks=[]
    for dn in ['PR_RCVDT','PR_DUEDT','TRD']:
        d=rows[0]['BK_TRDDT'] if dn=='TRD' else pr[dn]
        e=ent(p,d)
        for rn,rd in [('hu',ROUND_HALF_UP),('dn',ROUND_DOWN)]:
            if cents(pr['PR_AMTRC']*(1-e),rd)==amt: oks.append(dn+rn)
            if pr['PR_AMTRC']-cents(pr['PR_AMTRC']*e,rd)==amt: oks.append(dn+rn+'C')
    c[(era,tuple(oks))]+=1
    if not oks and len(ex[era])<6: ex[era].append((k,pr['PR_AMTRC'],pr['PR_AMTDU'],amt,amt/pr['PR_AMTRC'],pr['PR_RCVDT'],len(rows)))
for kk in sorted(c,key=str): print(kk,c[kk])
for kk,v in ex.items(): print(kk); [print('  ',x) for x in v]
EOF
